#include<bits/stdc++.h>
using namespace std;

int main(){
	int n;
	cin >> n;
	vector<string>s(n);
	for(int i=0;i<n;i++)cin >> s[i];

	map<string,int>count;
	for(int i=0;i<n;i++){
		for(int j=0;j<s[i].size();j++)if('A'<=s[i][j]&&s[i][j]<='Z')s[i][j]^=32;
		count[s[i]]++;
	}

	int ans=0;
	for(auto[k,v]:count)ans=max(ans,v);
	cout << ans << endl;
}
